INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1f6038ef-fc7c-4f57-bb86-782ad6e71207', '4-1', 'NB', 'TIN HOC 12 - BAI 1', 'Trí tuệ nhân tạo (AI) có khả năng thực hiện công việc nào sau đây?', '{"A":{"text":"Chỉ thực hiện công việc có tính lặp lại.","image":""},"B":{"text":"Làm công việc trí tuệ của con người như đọc chữ, hiểu tiếng nói.","image":""},"C":{"text":"Chỉ thực hiện các phép tính cơ bản.","image":""},"D":{"text":"Không thực hiện được công việc trí tuệ.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-16 03:28:35', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
