INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('0d4a1ffe-a65e-4444-befb-b3bca77c19d5', '4-1', 'TH', 'TIN 12 - BAI 3', 'Loại modem nào sau đây cho phép nối hai máy tính qua hệ thống chuyển mạch của mạng điện thoại công cộng?', '{"A":{"text":"Modem quay số.","image":""},"B":{"text":"Modem GSM 3G, 4G, 5G,…","image":""},"C":{"text":"Modem ADSL.","image":""},"D":{"text":"Modem quang.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('9049aace-0b0b-4c15-9aab-d4fb963d4685', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một mạng LAN nhỏ ở gia đình, lý do nào sau đây khiến người dùng có thể sử dụng hub thay vì switch?', '{"A":{"text":"Vì hub có nhiều cổng hơn.","image":""},"B":{"text":"Vì hub rẻ hơn và không cần thiết dùng switch với ít thiết bị.","image":""},"C":{"text":"Vì hub giúp tăng hiệu suất truyền dữ liệu.","image":""},"D":{"text":"Vì hub ít gây xung đột tín hiệu hơn.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ca6009a9-a00c-439e-accf-c3ea025db094', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây Wireless Access Point còn được gọi là “điểm truy cập không dây”?', '{"A":{"text":"Vì chỉ kết nối thiết bị qua cáp.","image":""},"B":{"text":"Vì nó là một router kết nối các LAN.","image":""},"C":{"text":"Vì giúp kết nối các thiết bị không dây trong mạng cục bộ.","image":""},"D":{"text":"Vì giúp tăng tốc độ truyền dữ liệu trong mạng.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('2099a5ad-9daa-4269-b1d8-7b998dbbc8e7', '4-1', 'TH', 'TIN 12 - BAI 3', 'Trong một router gia đình, cổng nào sau đây kết nối trực tiếp đến nhà cung cấp dịch vụ Internet?', '{"A":{"text":"Cổng LAN.","image":""},"B":{"text":"Cổng WAN.","image":""},"C":{"text":"Cổng USB.","image":""},"D":{"text":"Cổng Ethernet.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('284230be-5511-4b0f-9e2a-779796429d0a', '4-1', 'TH', 'TIN 12 - BAI 3', 'Lý do nào sau đây một số mạng gia đình cần sử dụng modem?', '{"A":{"text":"Vì modem làm tăng tốc độ mạng.","image":""},"B":{"text":"Vì modem chuyển tín hiệu số thành tín hiệu tương tự và ngược lại.","image":""},"C":{"text":"Vì modem có nhiều cổng hơn router.","image":""},"D":{"text":"Vì modem có thể tự động sửa lỗi mạng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1195bd3f-8cdc-49f6-87f6-71ee8de51b57', '4-1', 'TH', 'TIN 12 - BAI 3', 'Thiết bị nào sau đây xác định cổng kết nối giữa thiết bị gửi và thiết bị nhận, sau đó thiết lập tạm thời kênh truyền giữa hai cổng kết nối để truyền dữ liệu và huỷ kết nối sau khi hoàn thành việc truyền?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Router.","image":""},"C":{"text":"Hub.","image":""},"D":{"text":"Modem.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('cc12a6dc-b5a6-4bd6-a0da-8f5d6f3a3d1f', '4-1', 'TH', 'TIN 12 - BAI 3', 'Phát biểu nào sau đây đúng?', '{"A":{"text":"Mạng viễn thông sử dụng các modem để chuyển tiếp dữ liệu.","image":""},"B":{"text":"Thông thường LAN kết nối có dây các máy tính qua các thiết bị như switch hay hub trong một phạm vi địa lí nhất định.","image":""},"C":{"text":"Khi dùng hub thì tín hiệu đi từ máy gửi đến máy nhận sẽ không gây xung đột với tín hiệu của các cuộc truyền ở cổng khác.","image":""},"D":{"text":"Switch có chi phí rẻ hơn rất nhiều so với một hub có cùng số cổng.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('8284fce6-5aa4-4c99-b7d6-065ce3044a5f', '4-1', 'TH', 'TIN 12 - BAI 3', 'Wireless Access Point (WAP) có chức năng nào sau đây?', '{"A":{"text":"Chuyển đổi tín hiệu từ tín hiệu số sang tín hiệu tương tự và ngược lại, thường dùng khi kết nối LAN với Internet.","image":""},"B":{"text":"Dùng để kết nối các máy tính trong cùng LAN trực tiếp qua cáp mạng.","image":""},"C":{"text":"Dùng để kết nối các thiết bị đầu cuối qua sóng Wi-Fi giúp giảm chi phí thiết lập LAN hoặc kết nối với một LAN để mở rộng phạm vi làm việc.","image":""},"D":{"text":"Dùng để dẫn đường cho dữ liệu khi kết nối trên mạng diện rộng như Internet.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('dc727ed8-0196-4247-ac7d-4c8589696fcb', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong một mạng lớn, để giảm thiểu chi phí và tránh xung đột tín hiệu, cách tốt nhất là sử dụng kết hợp thiết bị nào sau đây?', '{"A":{"text":"Một router duy nhất.","image":""},"B":{"text":"Một switch kết hợp với hub ở tầng cuối.","image":""},"C":{"text":"Chỉ sử dụng nhiều hub.","image":""},"D":{"text":"Chỉ sử dụng nhiều switch.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:48', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('ab279a08-46d8-4a89-a4a3-27e7ebf9deef', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi muốn mở rộng phạm vi địa lý của mạng LAN, thiết bị nào sau đây có thể được thêm vào?', '{"A":{"text":"Switch.","image":""},"B":{"text":"Hub.","image":""},"C":{"text":"Wireless Access Point.","image":""},"D":{"text":"Router với nhiều cổng LAN.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('2b318159-49bb-449f-b297-fb9fbe25ec4f', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi truyền dữ liệu giữa hai máy tính ở hai LAN khác nhau, lý do nào sau đây dữ liệu phải chuyển qua cổng LAN và sau đó qua cổng WAN của router?', '{"A":{"text":"Để chuyển đổi từ tín hiệu số sang tín hiệu tương tự.","image":""},"B":{"text":"Để đảm bảo dữ liệu được định tuyến qua Internet.","image":""},"C":{"text":"Để tránh xung đột tín hiệu trong LAN.","image":""},"D":{"text":"Để bảo mật dữ liệu trong LAN.","image":""}}', 'B', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('5f22a513-a206-4ffe-b11b-40e230d59fef', '4-1', 'VD', 'TIN 12 - BAI 3', 'Trong trường hợp kết nối Internet không ổn định, thiết bị nào sau đây sẽ hữu ích để giúp router điều chỉnh tín hiệu mạng?', '{"A":{"text":"Hub.","image":""},"B":{"text":"Switch.","image":""},"C":{"text":"Modem.","image":""},"D":{"text":"Access Point.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('c4c9a7d8-f075-4e8b-b38a-abd911659f8d', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi sử dụng mạng di động (3G, 4G, 5G) để truyền dữ liệu từ LAN ra bên ngoài, loại modem nào sau đây thường được dùng?', '{"A":{"text":"Modem quay số (dial-up).","image":""},"B":{"text":"Modem ADSL.","image":""},"C":{"text":"Modem quang.","image":""},"D":{"text":"Modem GSM.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('7e1489c0-3508-4fc1-b1d4-c4ba54a63cbc', '4-1', 'VD', 'TIN 12 - BAI 3', 'Các LAN thường dùng loại cáp mạng nào?', '{"A":{"text":"FTP.","image":""},"B":{"text":"STP.","image":""},"C":{"text":"ETP.","image":""},"D":{"text":"UTP.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('85316f96-ceed-4aa5-8590-aa6ae7776862', '4-1', 'VD', 'TIN 12 - BAI 3', 'Khi kết nối máy tính với các thiết bị mạng, cần cắm một đầu giắc của cáp vào cổng nào của máy tính?', '{"A":{"text":"RJ45.","image":""},"B":{"text":"VJ45.","image":""},"C":{"text":"CJ45.","image":""},"D":{"text":"PJ45.","image":""}}', 'A', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e935c09a-a221-4844-8eea-019082f10f9e', '4-1', 'VD', 'TIN 12 - BAI 3', 'Phát biểu nào sau đây là sai?', '{"A":{"text":"Switch dùng để kết nối các đoạn mạng với nhau theo mô hình hình sao.","image":""},"B":{"text":"Hiện nay có hai loại Hub phổ biến là Active Hub và Smart Hub.","image":""},"C":{"text":"Router là một thiết bị mạng thuộc lớp 2 của mô hình OSI (Network Layer).","image":""},"D":{"text":"Modem có chức năng chuyển hoá các gói dữ liệu từ nhà cung cấp dịch vụ mạng (ISP) thành các kết nối Internet cho các router hoặc các thiết bị liên kết mạng khác qua địa chỉ IP.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-22 01:28:49', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('282f20e3-c4ac-4580-a611-4e5373b9ced6', 'trac_nghiem', 'NB', '', '', '{}', '', NULL, 'caaf3dce-041f-4f84-8ff6-0cde1bbc5dd3', '2026-09-22 09:14:42', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e807aea0-6298-4d71-a02c-c798b03311ef', '4-1', 'NB', 'TIN HOC 12 - BAI 4', 'Giao thức SMTP được sử dụng cho nhiệm vụ nào sau đây?', '{"A":{"text":"Nhận thư.","image":""},"B":{"text":"Truyền dữ liệu trên Internet.","image":""},"C":{"text":"Gửi thư.","image":""},"D":{"text":"Kết nối thiết bị qua Wi-Fi.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('1cd5bb93-e724-4933-8726-0b70a1455569', '4-1', 'NB', 'TIN HOC 12 - BAI 4', 'Giao thức nào sau đây quy định cách thức người nhận lấy thư trong email?', '{"A":{"text":"HTTP.","image":""},"B":{"text":"TCP.","image":""},"C":{"text":"IP.","image":""},"D":{"text":"POP3 hoặc IMAP.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('e4d85620-cdad-4add-b8a1-ee13003bd4d6', '4-1', 'NB', 'TIN HOC 12 - BAI 4', 'Mỗi thiết bị trong mạng cục bộ có một địa chỉ nào sau đây?', '{"A":{"text":"PI.","image":""},"B":{"text":"DNS.","image":""},"C":{"text":"MAC.","image":""},"D":{"text":"URL.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('d8bbbf5f-e853-483b-9325-50ab134fc688', '4-1', 'NB', 'TIN HOC 12 - BAI 4', 'Địa chỉ IP được sử dụng cho mục đích nào sau đây?', '{"A":{"text":"Xác định tên miền.","image":""},"B":{"text":"Định danh thiết bị trong mạng.","image":""},"C":{"text":"Định danh thiết bị khi kết nối Internet.","image":""},"D":{"text":"Phân loại thiết bị.","image":""}}', 'C', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
