INSERT INTO questions (id, type, level, lesson, content, options, answer, image, creator_id, created_at, updated_at) VALUES ('830aa942-97ec-483a-ad9b-40f12ced5829', '4-1', 'NB', 'TIN HOC 12 - BAI 4', 'Giao thức được sử dụng để kết nối tới server email và tải email xuống máy tính cá nhân thông qua 1 ứng dụng email như Outlook, Windows Mail…là giao thức nào sau đây?', '{"A":{"text":"Giao thức IMAP.","image":""},"B":{"text":"Giao thức MQT.","image":""},"C":{"text":"Giao thức SMTP.","image":""},"D":{"text":"Giao thức POP3.","image":""}}', 'D', NULL, '918ca52a-4656-4aeb-aa22-650c1d8946d3', '2026-09-29 01:16:34', '2026-10-04T01:10:06.939Z') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, level = EXCLUDED.level, lesson = EXCLUDED.lesson, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, image = EXCLUDED.image, updated_at = EXCLUDED.updated_at;
